macro_rules! register_conditional_shutdown {
    () => {
        # [doc = " Terminate the application on a signal if the given condition is true."] # [doc = ""] # [doc = " This can be used for different use cases. One of them (with the condition being always true) is"] # [doc = " just unconditionally terminate on the given signal."] # [doc = ""] # [doc = " Another is being able to turn on and off the behaviour by the shared flag."] # [doc = ""] # [doc = " The last one is handling double CTRL+C ‒ if the user presses CTRL+C, we would like to start a"] # [doc = " graceful shutdown. But if anything ever gets stuck in the shutdown, second CTRL+C (or other"] # [doc = " such termination signal) should terminate the application without further delay."] # [doc = ""] # [doc = " To do that, one can combine this with [`register`]. On the first run, the flag is `false` and"] # [doc = " this doesn't terminate. But then the flag is set to true during the first run and „arms“ the"] # [doc = " shutdown on the second run. Note that it matters in which order the actions are registered (the"] # [doc = " shutdown must go first). And yes, this also allows asking the user „Do you want to terminate“"] # [doc = " and disarming the abrupt shutdown if the user answers „No“."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " If the signal is one of the forbidden."] pub fn register_conditional_shutdown (signal : c_int , status : c_int , condition : Arc < AtomicBool > ,) -> Result < SigId , Error > { let action = move | | { if condition . load (Ordering :: SeqCst) { low_level :: exit (status) ; } } ; unsafe { low_level :: register (signal , action) } }
    };
}

register_conditional_shutdown!();